import { ActionBar, Button } from "@pisagor/solid";

export function Default() {
  return (
    <ActionBar>
      <ActionBar.Trigger
        asChild={(props) => (
          <Button {...props()} variant="outline">
            Open
          </Button>
        )}
      />
      <ActionBar.Content aria-label="Bulk actions">
        <ActionBar.Value count={3} />
        <ActionBar.Separator />
        <ActionBar.Body>
          <Button variant="ghost">Edit</Button>
          <Button variant="ghost">Export</Button>
        </ActionBar.Body>
        <ActionBar.Separator />
        <ActionBar.Close>×</ActionBar.Close>
      </ActionBar.Content>
    </ActionBar>
  );
}

import { ActionBar, Button } from "@pisagor/solid";
import {
  ArchiveIcon,
  DownloadIcon,
  PencilSimpleIcon,
  TrashIcon,
  XIcon,
} from "@pisagor/solid/icons";
import { createSignal } from "solid-js";
export function Gutter() {
  const gutters = ["24px", "32px"] as const;
  const [isOpen, setIsOpen] = createSignal(false);
  const [gutter, setGutter] = createSignal<(typeof gutters)[number]>("24px");

  return (
    <>
      <div class="flex flex-wrap gap-2">
        {gutters.map((value) => (
          <Button
            onClick={() => {
              setIsOpen(true);
              setGutter(value);
            }}
            variant={gutter() === value && isOpen() ? "secondary" : "outline"}
          >
            {`Gutter ${value}`}
          </Button>
        ))}
      </div>
      <ActionBar
        onOpenChange={setIsOpen}
        open={isOpen()}
        positioning={{ gutter: gutter(), placement: "bottom" }}
      >
        <ActionBar.Content aria-label="Bulk actions">
          <ActionBar.Value count={3} />
          <ActionBar.Separator />
          <ActionBar.Body>
            <Button variant="ghost">
              <PencilSimpleIcon />
              <span class="max-sm:sr-only">Edit</span>
            </Button>
            <Button variant="ghost">
              <DownloadIcon />
              <span class="max-sm:sr-only">Export</span>
            </Button>
            <Button variant="ghost">
              <ArchiveIcon />
              <span class="max-sm:sr-only">Archive</span>
            </Button>
            <ActionBar.Separator />
            <Button variant="destructive">
              <TrashIcon />
              <span class="max-sm:sr-only">Delete</span>
            </Button>
          </ActionBar.Body>
          <ActionBar.Separator />
          <ActionBar.Close
            asChild={(props) => (
              <Button
                {...props()}
                aria-label="Close"
                size="icon-md"
                variant="ghost"
              >
                <XIcon />
              </Button>
            )}
          />
        </ActionBar.Content>
      </ActionBar>
    </>
  );
}

import { ActionBar, Button } from "@pisagor/solid";
import {
  ArchiveIcon,
  DownloadIcon,
  PencilSimpleIcon,
  TrashIcon,
  XIcon,
} from "@pisagor/solid/icons";
import { createSignal } from "solid-js";
export function Placements() {
  type Placement = "bottom" | "bottom-start" | "bottom-end";
  const [isOpen, setIsOpen] = createSignal(false);
  const [placement, setPlacement] = createSignal<Placement>("bottom");

  const handleOpenChange = (nextPlacement: Placement) => {
    setIsOpen(true);
    setPlacement(nextPlacement);
  };

  return (
    <>
      <div class="flex flex-wrap gap-2">
        <Button
          onClick={() => handleOpenChange("bottom-start")}
          variant="outline"
        >
          Bottom start
        </Button>
        <Button onClick={() => handleOpenChange("bottom")} variant="outline">
          Bottom
        </Button>
        <Button
          onClick={() => handleOpenChange("bottom-end")}
          variant="outline"
        >
          Bottom end
        </Button>
      </div>
      <ActionBar
        onOpenChange={setIsOpen}
        open={isOpen()}
        positioning={{ placement: placement() }}
      >
        <ActionBar.Content aria-label="Bulk actions">
          <ActionBar.Value count={5} />
          <ActionBar.Separator />
          <ActionBar.Body>
            <Button variant="ghost">
              <PencilSimpleIcon />
              <span class="max-sm:sr-only">Edit</span>
            </Button>
            <Button variant="ghost">
              <DownloadIcon />
              <span class="max-sm:sr-only">Export</span>
            </Button>
            <Button variant="ghost">
              <ArchiveIcon />
              <span class="max-sm:sr-only">Archive</span>
            </Button>
            <ActionBar.Separator />
            <Button variant="destructive">
              <TrashIcon />
              <span class="max-sm:sr-only">Delete</span>
            </Button>
          </ActionBar.Body>
          <ActionBar.Separator />
          <ActionBar.Close
            asChild={(props) => (
              <Button
                {...props()}
                aria-label="Close"
                size="icon-md"
                variant="ghost"
              >
                <XIcon />
              </Button>
            )}
          />
        </ActionBar.Content>
      </ActionBar>
    </>
  );
}

import { ActionBar, AlertDialog, Button } from "@pisagor/solid";
import { TrashIcon, XIcon } from "@pisagor/solid/icons";
export function WithDialog() {
  return (
    <ActionBar>
      <ActionBar.Trigger
        asChild={(props) => (
          <Button {...props()} variant="outline">
            Open
          </Button>
        )}
      />
      <ActionBar.Content aria-label="Order bulk actions">
        <ActionBar.Value count={3} />
        <ActionBar.Separator />
        <ActionBar.Body>
          <AlertDialog
            actions={
              <>
                <AlertDialog.Cancel>Cancel</AlertDialog.Cancel>
                <AlertDialog.CloseTrigger
                  asChild={(props) => (
                    <AlertDialog.Action {...props()} variant="destructive">
                      Delete
                    </AlertDialog.Action>
                  )}
                />
              </>
            }
            description="This action cannot be undone."
            title="Delete selected orders?"
            trigger={(props) => (
              <Button {...props} variant="destructive">
                <TrashIcon />
                <span class="max-sm:sr-only">Delete</span>
              </Button>
            )}
          />
        </ActionBar.Body>
        <ActionBar.Separator />
        <ActionBar.Close
          asChild={(props) => (
            <Button
              {...props()}
              aria-label="Close"
              size="icon-md"
              variant="ghost"
            >
              <XIcon />
            </Button>
          )}
        />
      </ActionBar.Content>
    </ActionBar>
  );
}

