import { Alert, Button } from "@pisagor/solid";
import { ChecksIcon } from "@pisagor/solid/icons";
export function Compound() {
  return (
    <Alert.Root variant="info">
      <ChecksIcon />
      <Alert.Title>Deployment successful</Alert.Title>
      <Alert.Description>
        You can now start building your next great project.
      </Alert.Description>
      <Alert.Action>
        <Button size="xs">Update</Button>
      </Alert.Action>
    </Alert.Root>
  );
}

import { Alert } from "@pisagor/solid";
import { MagicWandIcon } from "@pisagor/solid/icons";

export function CustomColor() {
  return (
    <Alert
      class="border-purple-500/32 bg-purple-500/5 [&_svg]:text-purple-500"
      description="This alert uses a custom color."
      icon={<MagicWandIcon />}
      title="Custom color alert"
    />
  );
}

import { Alert } from "@pisagor/solid";

export function Default() {
  return (
    <Alert
      description="You can add icons to alerts to provide visual context and improve user experience."
      title="Icons improve context"
    />
  );
}

import { Alert } from "@pisagor/solid";
import {
  CheckCircleIcon,
  ChecksIcon,
  ClockCounterClockwiseIcon,
  WarningIcon,
} from "@pisagor/solid/icons";

export function Variants() {
  return (
    <div class="flex flex-col gap-2">
      <Alert
        description="You can now start building your next great project."
        icon={<ChecksIcon />}
        title="Deployment successful"
        variant="default"
      />
      <Alert
        description="Your session has expired. Please log in again."
        icon={<WarningIcon />}
        title="Session expired"
        variant="destructive"
      />
      <Alert
        description="A new update is available. Review the update when you're ready."
        icon={<ClockCounterClockwiseIcon />}
        title="New update available"
