import type { AppShellProps as BaseAppShellRootProps } from "@pisagor/props";
import { appShellRecipe } from "@pisagor/recipes";
import type { ComponentProps, JSX } from "solid-js";
import {
  createEffect,
  createMemo,
  createSignal,
  onCleanup,
  splitProps,
} from "solid-js";
import {
  APP_SHELL_DEFAULT_INSPECTOR_RESIZABLE_PROPS,
  APP_SHELL_DEFAULT_PANEL_RESIZABLE_PROPS,
  AppShellContext,
  type AppShellFixedStackVar,
  type AppShellPlacement,
  type AppShellRailState,
  type AppShellRegionVar,
  type AppShellSideState,
  AppShellStylesContext,
  ZERO_FIXED_STACK_VARS,
  ZERO_REGION_VARS,
} from "./app-shell.context";

const APP_SHELL_GRID_COLUMNS = `
  var(--app-shell-start-inspector-width, 0px)
  var(--app-shell-start-rail-width, 0px)
  var(--app-shell-start-panel-width, 0px)
  minmax(0, 1fr)
  var(--app-shell-end-panel-width, 0px)
  var(--app-shell-end-rail-width, 0px)
  var(--app-shell-end-inspector-width, 0px)
`;

const APP_SHELL_CONTENT_ROW =
  '"start-inspector start-rail start-panel main end-panel end-rail end-inspector"';

const APP_SHELL_NAV_ROW =
  '"start-inspector navigation navigation navigation navigation navigation end-inspector"';

const APP_SHELL_BANNER_ROW =
  '"banner banner banner banner banner banner banner"';

export interface AppShellRootProps
  extends ComponentProps<"div">,
    BaseAppShellRootProps {}

export function AppShellRoot(props: AppShellRootProps): JSX.Element {
  const [local, rest] = splitProps(props, [
    "children",
    "recipe",
    "class",
    "style",
  ]);
  const slots = createMemo(() => (local.recipe ?? appShellRecipe)());
  const [regionRevision, setRegionRevision] = createSignal(0);
  const [regionVars, setRegionVars] = createSignal({ ...ZERO_REGION_VARS });
  const [fixedStackVars, setFixedStackVars] = createSignal({
    ...ZERO_FIXED_STACK_VARS,
  });
  const panelStates = {
    current: {} as Partial<Record<AppShellPlacement, AppShellSideState>>,
  };
  const inspectorStates = {
    current: {} as Partial<Record<AppShellPlacement, AppShellSideState>>,
  };
  const railStates = {
    current: {} as Partial<Record<AppShellPlacement, AppShellRailState>>,
  };
  const shellRef = { current: null as HTMLDivElement | null };
  const [regionResizing, setRegionResizing] = createSignal(false);

  const setRegionVar = (name: AppShellRegionVar, value: string) => {
    setRegionVars((current) => {
      if (current[name] === value) return current;
      return { ...current, [name]: value };
    });
  };

  const setFixedStackVar = (name: AppShellFixedStackVar, value: string) => {
    setFixedStackVars((current) => {
      if (current[name] === value) return current;
      return { ...current, [name]: value };
    });
  };

  createEffect(() => {
    const onKeyDown = (event: KeyboardEvent) => {
      if ((event.metaKey || event.ctrlKey) && event.code === "Backslash") {
        event.preventDefault();
        panelStates.current.start?.toggle();
      }
    };
    window.addEventListener("keydown", onKeyDown);
    onCleanup(() => window.removeEventListener("keydown", onKeyDown));
  });

  const notifyRegionChange = () => setRegionRevision((r) => r + 1);

  const gridStyle = {
    "grid-template-areas": [
      APP_SHELL_BANNER_ROW,
      APP_SHELL_NAV_ROW,
      APP_SHELL_CONTENT_ROW,
    ].join(" "),
    "grid-template-columns": APP_SHELL_GRID_COLUMNS,
    "grid-template-rows": "auto auto auto",
  };

  return (
    <AppShellStylesContext
      value={{
        get slots() {
          return slots();
        },
        variants: {},
      }}
    >
      <AppShellContext
        value={{
          defaultInspectorResizableProps:
            APP_SHELL_DEFAULT_INSPECTOR_RESIZABLE_PROPS,
          defaultPanelResizableProps: APP_SHELL_DEFAULT_PANEL_RESIZABLE_PROPS,
          fixedStackVars,
          inspectorStates,
          notifyRegionChange,
          panelStates,
          railStates,
          regionResizing,
          regionRevision,
          regionVars,
          setFixedStackVar,
          setRegionResizing,
          setRegionVar,
          shellRef,
        }}
      >
        <div
          {...rest}
          class={slots().base({ class: local.class })}
          data-part="root"
          data-resizing={regionResizing() ? "" : undefined}
          data-scope="app-shell"
          ref={(el) => {
            shellRef.current = el;
          }}
          style={{
            ...regionVars(),
            ...fixedStackVars(),
            ...gridStyle,
            ...(typeof local.style === "object" &&
            local.style &&
            !Array.isArray(local.style)
              ? (local.style as Record<string, string>)
              : {}),
          }}
        >
          {local.children}
        </div>
      </AppShellContext>
    </AppShellStylesContext>
  );
}

import { appShellRecipe } from "@pisagor/recipes";
import type { Accessor } from "solid-js";
import { createMemo, createSignal } from "solid-js";
import { createSlotRecipeContext } from "../../internal/create-slot-recipe-context";
import { createContext } from "../../utils";

export type AppShellPlacement = "start" | "end";
export type AppShellRegionPosition = "fixed" | "relative";
export type AppShellResizeHandlePosition = "bottom" | "center" | "top";

export interface AppShellResizableProps {
  enabled?: boolean;
  handlePosition?: AppShellResizeHandlePosition;
}

export const APP_SHELL_DEFAULT_PANEL_RESIZABLE_PROPS = {
  enabled: true,
  handlePosition: "top",
} as const satisfies Required<
  Pick<AppShellResizableProps, "enabled" | "handlePosition">
>;

export const APP_SHELL_DEFAULT_INSPECTOR_RESIZABLE_PROPS = {
  enabled: true,
  handlePosition: "top",
} as const satisfies Required<
  Pick<AppShellResizableProps, "enabled" | "handlePosition">
>;

export type AppShellFixedStackVar =
  | "--app-shell-banner-height"
  | "--app-shell-navigation-height";

export type AppShellRegionVar =
  | "--app-shell-end-inspector-width"
  | "--app-shell-end-panel-width"
  | "--app-shell-end-rail-width"
  | "--app-shell-start-inspector-width"
  | "--app-shell-start-panel-width"
  | "--app-shell-start-rail-width";

export interface AppShellSideState {
  open: Accessor<boolean>;
  setOpen: (open: boolean | ((current: boolean) => boolean)) => void;
  toggle: () => void;
}

export interface AppShellRailState {
  activeRailId: Accessor<string | undefined>;
  placement: AppShellPlacement;
  setActiveRailId: (id: string) => void;
}

export type MutableRef<T> = { current: T };

interface AppShellStateValue {
  inspectorStates: MutableRef<
    Partial<Record<AppShellPlacement, AppShellSideState>>
  >;
  notifyRegionChange: () => void;
  panelStates: MutableRef<
    Partial<Record<AppShellPlacement, AppShellSideState>>
  >;
  railStates: MutableRef<Partial<Record<AppShellPlacement, AppShellRailState>>>;
  regionResizing: Accessor<boolean>;
  regionRevision: Accessor<number>;
  regionVars: Accessor<Record<AppShellRegionVar, string>>;
  fixedStackVars: Accessor<Record<AppShellFixedStackVar, string>>;
  defaultInspectorResizableProps: typeof APP_SHELL_DEFAULT_INSPECTOR_RESIZABLE_PROPS;
  defaultPanelResizableProps: typeof APP_SHELL_DEFAULT_PANEL_RESIZABLE_PROPS;
  setRegionResizing: (resizing: boolean) => void;
  setFixedStackVar: (name: AppShellFixedStackVar, value: string) => void;
  setRegionVar: (name: AppShellRegionVar, value: string) => void;
  shellRef: MutableRef<HTMLDivElement | null>;
}

interface UseSideStateOptions {
  getControlledOpen?: () => boolean | undefined;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
}

export const ZERO_FIXED_STACK_VARS: Record<AppShellFixedStackVar, string> = {
  "--app-shell-banner-height": "0px",
  "--app-shell-navigation-height": "0px",
};

export const ZERO_REGION_VARS: Record<AppShellRegionVar, string> = {
  "--app-shell-end-inspector-width": "0px",
  "--app-shell-end-panel-width": "0px",
  "--app-shell-end-rail-width": "0px",
  "--app-shell-start-inspector-width": "0px",
  "--app-shell-start-panel-width": "0px",
  "--app-shell-start-rail-width": "0px",
};

const { Context: AppShellStylesContext, useStyles: useAppShellStyles } =
  createSlotRecipeContext({
    name: "AppShell",
    recipe: appShellRecipe,
  });

export { AppShellStylesContext, useAppShellStyles };

export const { AppShellContext, useAppShell: useAppShellState } =
  createContext("AppShell")<AppShellStateValue>();

/** Nearest app-shell styles + layout state (`slots` stays reactive). */
export function useAppShell() {
  const styles = useAppShellStyles();
  const state = useAppShellState();
  return {
    ...state,
    get slots() {
      return styles.slots;
    },
  };
}

export function useSideState({
  defaultOpen = false,
  getControlledOpen,
  onOpenChange,
}: UseSideStateOptions): AppShellSideState {
  const [uncontrolled, setUncontrolled] = createSignal(defaultOpen);
  const open = createMemo(() => {
    const controlled = getControlledOpen?.();
    return controlled !== undefined ? !!controlled : uncontrolled();
  });

  const setOpenValue = (next: boolean) => {
    if (getControlledOpen?.() === undefined) setUncontrolled(next);
    onOpenChange?.(next);
  };

  const setOpen = (value: boolean | ((current: boolean) => boolean)) => {
    setOpenValue(typeof value === "function" ? value(open()) : value);
  };

  const toggle = () => setOpenValue(!open());

  return { open, setOpen, toggle };
}

import { cn } from "@pisagor/utils";
import type { ComponentProps, JSX } from "solid-js";
import { splitProps } from "solid-js";
import type { AppShellRegionPosition } from "./app-shell.context";
import { useAppShellStyles } from "./app-shell.context";
import { APP_SHELL_BANNER_HEIGHT_VAR } from "./constants";
import { regionPositionClasses, useSyncFixedRegionHeight } from "./region";

export interface AppShellBannerProps extends ComponentProps<"div"> {
  position?: AppShellRegionPosition;
}

export function AppShellBanner(props: AppShellBannerProps): JSX.Element {
  const [local, rest] = splitProps(props, ["position", "class", "style"]);
  let bannerEl: HTMLDivElement | undefined;
  const styles = useAppShellStyles();
  const position = () => local.position ?? "fixed";
  useSyncFixedRegionHeight(
    () => bannerEl,
    position,
    APP_SHELL_BANNER_HEIGHT_VAR,
  );

  return (
    <div
      {...rest}
      class={cn(
        styles.slots.banner(),
        regionPositionClasses(styles.slots, position(), "row", "banner"),
        local.class,
      )}
      data-part="banner"
      data-position={position()}
      data-scope="app-shell"
      ref={(el) => {
        bannerEl = el;
      }}
      style={{
        "grid-area": "banner",
        ...(typeof local.style === "object" &&
        local.style &&
        !Array.isArray(local.style)
          ? (local.style as Record<string, string>)
          : {}),
      }}
    />
  );
}

export const APP_SHELL_RAIL_WIDTH = "3.5rem";
export const APP_SHELL_BANNER_HEIGHT_VAR = "--app-shell-banner-height" as const;
export const APP_SHELL_NAVIGATION_HEIGHT_VAR =
  "--app-shell-navigation-height" as const;

import { cn } from "@pisagor/utils";
import type { ComponentProps, JSX } from "solid-js";
import { createSignal, Show, splitProps } from "solid-js";
import {
  ArrowsInLineHorizontalIcon,
  ArrowsOutLineHorizontalIcon,
} from "../../internal/icons";
import type { ButtonProps } from "../button";
import { Resizable } from "../resizable";
import { ScrollArea } from "../scroll-area";
import type {
  AppShellPlacement,
  AppShellRegionPosition,
  AppShellResizableProps,
} from "./app-shell.context";
import { useAppShellState, useAppShellStyles } from "./app-shell.context";
import {
  gridAreaFor,
  mergeResizableProps,
  regionPositionClasses,
  regionVarFor,
  useAppShellSideOpen,
  useRegionWidth,
  useRegisteredSideState,
  useShellRegionResizeCallbacks,
} from "./region";
import { AppShellSideTrigger } from "./side-trigger";

export interface AppShellInspectorProps extends ComponentProps<"aside"> {
  placement?: AppShellPlacement;
  position?: AppShellRegionPosition;
  defaultOpen?: boolean;
  defaultWidth?: number;
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  resizableProps?: AppShellResizableProps;
}

export interface AppShellInspectorTriggerProps
  extends Omit<ButtonProps, "children"> {
  placement?: AppShellPlacement;
  children?: JSX.Element;
  off?: JSX.Element;
  on?: JSX.Element;
}

export type AppShellInspectorHeaderProps = ComponentProps<"div">;
export type AppShellInspectorContentProps = ComponentProps<"div">;
export type AppShellInspectorFooterProps = ComponentProps<"div">;

export function AppShellInspector(props: AppShellInspectorProps): JSX.Element {
  const [local, rest] = splitProps(props, [
    "placement",
    "position",
    "defaultOpen",
    "defaultWidth",
    "open",
    "children",
    "onOpenChange",
    "class",
    "style",
    "resizableProps",
  ]);
  const placement = () => local.placement ?? "end";
  const position = () => local.position ?? "fixed";
  const styles = useAppShellStyles();
  const { defaultInspectorResizableProps, inspectorStates } =
    useAppShellState();
  const resizableProps = () =>
    mergeResizableProps(defaultInspectorResizableProps, local.resizableProps);
  const side = useRegisteredSideState({
    defaultOpen: local.defaultOpen ?? false,
    getControlledOpen: () => local.open,
    onOpenChange: local.onOpenChange,
    placement: placement(),
    statesRef: inspectorStates,
  });
  const regionVar = regionVarFor(placement(), "inspector");
  const [widthPx, setWidthPx] = createSignal(local.defaultWidth ?? 320);
  const resolvedWidth = () => (side.open() ? `${widthPx()}px` : "0px");
  const regionResizeCallbacks = useShellRegionResizeCallbacks(regionVar);

  useRegionWidth(regionVar, resolvedWidth);

  return (
    <aside
      {...rest}
      class={cn(
        styles.slots.inspector(),
        placement() === "start" ? "border-e" : "border-s",
        regionPositionClasses(
          styles.slots,
          position(),
          "column",
          undefined,
          "inspector",
        ),
        side.open() ? "opacity-100" : "pointer-events-none opacity-0",
        local.class,
      )}
      data-part="inspector"
      data-placement={placement()}
      data-position={position()}
      data-scope="app-shell"
      data-state={side.open() ? "open" : "closed"}
      style={{
        "grid-area": gridAreaFor(placement(), "inspector"),
        ...(typeof local.style === "object" &&
        local.style &&
        !Array.isArray(local.style)
          ? (local.style as Record<string, string>)
          : {}),
      }}
    >
      <Show when={side.open() && resizableProps().enabled}>
        <Resizable.EdgeHandle
          {...regionResizeCallbacks}
          handlePosition={resizableProps().handlePosition}
          label={`Resize ${placement()} inspector`}
          onWidthChange={setWidthPx}
          placement={placement()}
          width={widthPx()}
        />
      </Show>
      <div class={styles.slots.sideBody()}>{local.children}</div>
    </aside>
  );
}

export function AppShellInspectorHeader(
  props: AppShellInspectorHeaderProps,
): JSX.Element {
  const [local, rest] = splitProps(props, ["class"]);
  const styles = useAppShellStyles();
  return (
    <div
      {...rest}
      class={styles.slots.inspectorHeader({ class: local.class })}
      data-part="inspector-header"
      data-scope="app-shell"
    />
  );
}

export function AppShellInspectorContent(
  props: AppShellInspectorContentProps,
): JSX.Element {
  const [local, rest] = splitProps(props, ["class"]);
  const styles = useAppShellStyles();
  return (
    <ScrollArea class={styles.slots.scrollArea()}>
      <div
        {...rest}
        class={styles.slots.inspectorContent({ class: local.class })}
        data-part="inspector-content"
        data-scope="app-shell"
      />
    </ScrollArea>
  );
}

export function AppShellInspectorFooter(
  props: AppShellInspectorFooterProps,
): JSX.Element {
  const [local, rest] = splitProps(props, ["class"]);
  const styles = useAppShellStyles();
  return (
    <div
      {...rest}
      class={styles.slots.inspectorFooter({ class: local.class })}
      data-part="inspector-footer"
      data-scope="app-shell"
    />
  );
}

export function AppShellInspectorTrigger(
  props: AppShellInspectorTriggerProps,
): JSX.Element {
  const [local, rest] = splitProps(props, [
    "placement",
    "children",
    "off",
    "on",
    "onClick",
    "class",
  ]);
  const placement = () => local.placement ?? "end";
  const { inspectorStates } = useAppShellState();
  const open = useAppShellSideOpen(placement(), inspectorStates);

  return (
    <AppShellSideTrigger
      {...rest}
      class={local.class}
      data-part="inspector-trigger"
      defaultOff={<ArrowsOutLineHorizontalIcon />}
      defaultOn={<ArrowsInLineHorizontalIcon />}
      off={local.off}
      on={local.on}
      onClick={local.onClick}
      open={open()}
      placement={placement()}
      toggle={() => {
        inspectorStates.current[placement()]?.toggle();
      }}
    >
      {local.children}
    </AppShellSideTrigger>
  );
}

import { cn } from "@pisagor/utils";
