import { createContext } from "../../utils";
import type { AppShellRailState } from "./app-shell.context";

export const { AppShellRailContext, useAppShellRail } =
  createContext("AppShellRail")<AppShellRailState>();

import { cn } from "@pisagor/utils";
import type { ComponentProps, JSX } from "solid-js";
import { Show, splitProps } from "solid-js";
import { Button, type ButtonProps } from "../button";
import { Tooltip, type TooltipProps } from "../tooltip";
import type {
  AppShellPlacement,
  AppShellRegionPosition,
} from "./app-shell.context";
import { useAppShellState, useAppShellStyles } from "./app-shell.context";
import { APP_SHELL_RAIL_WIDTH } from "./constants";
import { AppShellRailContext, useAppShellRail } from "./rail.context";
import {
  gridAreaFor,
  regionPositionClasses,
  regionVarFor,
  useRegionWidth,
  useRegisteredRailState,
} from "./region";

export interface AppShellRailProps extends ComponentProps<"aside"> {
  placement?: AppShellPlacement;
  position?: AppShellRegionPosition;
  activeRailId?: string;
  defaultActiveRailId?: string;
  onActiveRailIdChange?: (id: string) => void;
}

export interface AppShellRailItemProps extends ButtonProps {
  isActive?: boolean;
  opensPanel?: boolean;
  panelPlacement?: AppShellPlacement;
  railId?: string;
  tooltip?: string | Omit<TooltipProps, "children">;
}

export function AppShellRail(props: AppShellRailProps): JSX.Element {
  const [local, rest] = splitProps(props, [
    "placement",
    "position",
    "defaultActiveRailId",
    "activeRailId",
    "children",
    "onActiveRailIdChange",
    "class",
    "style",
  ]);
  const placement = () => local.placement ?? "start";
  const position = () => local.position ?? "fixed";
  const styles = useAppShellStyles();
  const { railStates } = useAppShellState();
  const regionVar = regionVarFor(placement(), "rail");
  const railState = useRegisteredRailState({
    defaultActiveRailId: local.defaultActiveRailId,
    getActiveRailId: () => local.activeRailId,
    onActiveRailIdChange: local.onActiveRailIdChange,
    placement: placement(),
    statesRef: railStates,
  });

  useRegionWidth(regionVar, () => APP_SHELL_RAIL_WIDTH);

  return (
    <AppShellRailContext value={railState}>
      <aside
        {...rest}
        class={cn(
          styles.slots.rail(),
          placement() === "start" ? "border-e" : "border-s",
          regionPositionClasses(styles.slots, position(), "column"),
          local.class,
        )}
        data-part="rail"
        data-placement={placement()}
        data-position={position()}
        data-scope="app-shell"
        style={{
          "grid-area": gridAreaFor(placement(), "rail"),
          ...(typeof local.style === "object" &&
          local.style &&
          !Array.isArray(local.style)
            ? (local.style as Record<string, string>)
            : {}),
        }}
      >
        {local.children}
      </aside>
    </AppShellRailContext>
  );
}

export function AppShellRailItem(props: AppShellRailItemProps): JSX.Element {
  const [local, rest] = splitProps(props, [
    "panelPlacement",
    "size",
    "variant",
    "isActive",
    "opensPanel",
    "railId",
    "tooltip",
    "onClick",
    "class",
    "children",
  ]);
  const {
    activeRailId,
    placement: railPlacement,
    setActiveRailId,
  } = useAppShellRail();
  const panelPlacement = () => local.panelPlacement ?? railPlacement;
  const styles = useAppShellStyles();
  const { panelStates } = useAppShellState();
  const active = () =>
    local.isActive ??
    (local.railId !== undefined && activeRailId() === local.railId);

  const button = (
    <Button
      {...rest}
      aria-current={active() ? "page" : undefined}
      class={styles.slots.railItem({ class: local.class })}
      clickEffect={false}
      data-active={active()}
      data-part="rail-item"
      data-rail-id={local.railId}
      data-scope="app-shell"
      onClick={(event) => {
        if (typeof local.onClick === "function") local.onClick(event);
        if (local.railId) setActiveRailId(local.railId);
        if (local.opensPanel) {
          panelStates.current[panelPlacement()]?.setOpen(true);
        }
      }}
      size={local.size ?? "icon-md"}
      variant={local.variant ?? "ghost"}
    >
      {local.children}
    </Button>
  );

  return (
    <Show fallback={button} when={local.tooltip}>
      {(tip) => {
        const tooltipProps =
          typeof tip() === "string"
            ? ({ content: tip() as string } as Omit<TooltipProps, "children">)
            : (tip() as Omit<TooltipProps, "children">);
        return (
          <Tooltip
            {...tooltipProps}
            positioning={{
              placement: railPlacement === "end" ? "left" : "right",
              ...tooltipProps.positioning,
            }}
          >
            {button}
          </Tooltip>
        );
      }}
    </Show>
  );
}

import type { AppShellRecipe } from "@pisagor/recipes";
import { createEffect, createMemo, createSignal, onCleanup } from "solid-js";
import type {
  AppShellFixedStackVar,
  AppShellPlacement,
  AppShellRailState,
  AppShellRegionPosition,
  AppShellRegionVar,
  AppShellResizableProps,
  AppShellSideState,
  MutableRef,
} from "./app-shell.context";
import { useAppShellState, useSideState } from "./app-shell.context";

export function useRegionWidth(name: AppShellRegionVar, width: () => string) {
  const { setRegionVar } = useAppShellState();

  createEffect(() => {
    const value = width();
    setRegionVar(name, value);
    onCleanup(() => setRegionVar(name, "0px"));
  });
}

export function regionVarFor(
  placement: AppShellPlacement,
  region: "inspector" | "panel" | "rail",
) {
  return `--app-shell-${placement}-${region}-width` as AppShellRegionVar;
}

export function gridAreaFor(
  placement: AppShellPlacement,
  region: "inspector" | "panel" | "rail",
) {
  return `${placement}-${region}` as const;
}

export function mergeResizableProps(
  defaults: Required<
    Pick<AppShellResizableProps, "enabled" | "handlePosition">
  >,
  override?: AppShellResizableProps,
): Required<Pick<AppShellResizableProps, "enabled" | "handlePosition">> {
  return {
    enabled: override?.enabled ?? defaults.enabled,
    handlePosition: override?.handlePosition ?? defaults.handlePosition,
  };
}

export function useShellRegionResizeCallbacks(regionVar: AppShellRegionVar) {
  const { setRegionResizing, setRegionVar } = useAppShellState();

  return {
    onResizeChange: (nextWidth: number) => {
      setRegionVar(regionVar, `${nextWidth}px`);
    },
    onResizeEnd: () => setRegionResizing(false),
    onResizeStart: () => setRegionResizing(true),
  };
}

export function regionPositionClasses(
  slots: AppShellRecipe,
  position: AppShellRegionPosition = "fixed",
  orientation: "column" | "row" = "column",
  rowLayer?: "banner" | "header" | "navigation",
  columnLayer?: "inspector",
) {
  if (position === "relative") {
    return orientation === "column"
      ? slots.regionRelativeColumn()
      : slots.regionRelativeRow();
  }

  if (orientation === "column") {
    if (columnLayer === "inspector") {
      return slots.regionStickyInspector();
    }
    return slots.regionStickyColumn();
  }

  if (rowLayer === "banner") {
    return slots.regionStickyBanner();
  }

  if (rowLayer === "navigation") {
    return slots.regionStickyNavigation();
  }

  return slots.regionStickyHeader();
}

export function useSyncFixedRegionHeight(
  getEl: () => HTMLElement | undefined | null,
  position: () => AppShellRegionPosition,
  cssVar: AppShellFixedStackVar,
) {
  const { setFixedStackVar } = useAppShellState();

  createEffect(() => {
    const element = getEl();
    const pos = position();

    if (pos !== "fixed" || !element) {
      setFixedStackVar(cssVar, "0px");
      return;
    }

    const syncHeight = () => {
      setFixedStackVar(cssVar, `${element.offsetHeight}px`);
    };

    syncHeight();
    const observer = new ResizeObserver(syncHeight);
    observer.observe(element);

    onCleanup(() => {
      observer.disconnect();
      setFixedStackVar(cssVar, "0px");
    });
  });
}

export function useAppShellSideOpen(
  placement: AppShellPlacement,
  statesRef: MutableRef<Partial<Record<AppShellPlacement, AppShellSideState>>>,
) {
  const { regionRevision } = useAppShellState();
  return () => {
    regionRevision();
    return statesRef.current[placement]?.open() ?? false;
  };
}

export function useRegisteredSideState({
  placement,
  defaultOpen,
  getControlledOpen,
  statesRef,
  onOpenChange,
}: {
  getControlledOpen?: () => boolean | undefined;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  placement: AppShellPlacement;
  statesRef: MutableRef<Partial<Record<AppShellPlacement, AppShellSideState>>>;
}) {
  const { notifyRegionChange } = useAppShellState();
  const side = useSideState({ defaultOpen, getControlledOpen, onOpenChange });

  const setOpen = (value: boolean | ((current: boolean) => boolean)) => {
    side.setOpen(value);
    notifyRegionChange();
  };

  const toggle = () => {
    side.toggle();
    notifyRegionChange();
  };

  const registeredSide: AppShellSideState = {
    open: side.open,
    setOpen,
    toggle,
  };

  statesRef.current[placement] = registeredSide;

  createEffect(() => {
    notifyRegionChange();
    onCleanup(() => {
      delete statesRef.current[placement];
    });
  });

  return registeredSide;
}

export function useRegisteredRailState({
  placement,
  defaultActiveRailId,
  getActiveRailId,
  statesRef,
  onActiveRailIdChange,
}: {
  getActiveRailId?: () => string | undefined;
  defaultActiveRailId?: string;
  onActiveRailIdChange?: (id: string) => void;
  placement: AppShellPlacement;
  statesRef: MutableRef<Partial<Record<AppShellPlacement, AppShellRailState>>>;
}) {
  const [uncontrolled, setUncontrolled] = createSignal(defaultActiveRailId);
  const activeRailId = createMemo(() => {
    const controlled = getActiveRailId?.();
    return controlled !== undefined ? controlled : uncontrolled();
  });

  const setActiveRailId = (id: string) => {
    if (getActiveRailId?.() === undefined) setUncontrolled(id);
    onActiveRailIdChange?.(id);
  };

  const railState: AppShellRailState = {
    activeRailId,
    placement,
    setActiveRailId,
  };

  statesRef.current[placement] = railState;

  createEffect(() => {
    onCleanup(() => {
      delete statesRef.current[placement];
    });
  });

  return railState;
}

import type { JSX } from "solid-js";
import { splitProps } from "solid-js";
import { Button, type ButtonProps } from "../button";
import { Swap } from "../swap";
import type { AppShellPlacement } from "./app-shell.context";
import { useAppShellStyles } from "./app-shell.context";

export function AppShellSideTrigger(
  props: {
    "aria-label"?: string;
    children?: JSX.Element;
    defaultOff: JSX.Element;
    defaultOn: JSX.Element;
    open: boolean;
    placement: AppShellPlacement;
    toggle: () => void;
    on?: JSX.Element;
    off?: JSX.Element;
  } & Omit<ButtonProps, "aria-label" | "children" | "onClick"> & {
      onClick?: ButtonProps["onClick"];
    },
): JSX.Element {
  const [local, rest] = splitProps(props, [
    "aria-label",
    "children",
    "defaultOff",
    "defaultOn",
    "open",
    "placement",
    "toggle",
    "on",
    "off",
    "onClick",
    "class",
  ]);
  const styles = useAppShellStyles();
  const resolvedOff = () => local.off ?? local.defaultOff;
  const resolvedOn = () => local.on ?? local.defaultOn;

  return (
    <Button
      {...rest}
      aria-label={local["aria-label"] ?? `Toggle ${local.placement} region`}
      aria-pressed={local.open}
      class={styles.slots.inline({ class: local.class })}
      data-placement={local.placement}
      data-scope="app-shell"
      data-state={local.open ? "open" : "closed"}
      onClick={(event) => {
        if (typeof local.onClick === "function") local.onClick(event);
        local.toggle();
      }}
      size="icon-md"
      variant="ghost"
    >
      {local.children ?? (
        <Swap off={resolvedOff()} on={resolvedOn()} swap={local.open} />
      )}
    </Button>
  );
}

import { AppShellRoot } from "./app-shell";
import { AppShellBanner } from "./banner";
import {
