import {
  type AvatarFallbackProps,
  type AvatarImageProps,
  Avatar as AvatarPrimitive,
  type AvatarRootProps as AvatarPrimitiveRootProps,
} from "@ark-ui/solid/avatar";
import type { AvatarProps as BaseAvatarRootProps } from "@pisagor/props";
import {
  type AvatarRecipeSlot,
  type AvatarVariantProps,
  avatarRecipe,
} from "@pisagor/recipes";
import type { Component, JSX } from "solid-js";
import { Show, splitProps } from "solid-js";
import { createSlotRecipeContext } from "../../internal/create-slot-recipe-context";
import type { VariantClassNames } from "../../internal/types";

// #region Context
const { withContext, withProvider } = createSlotRecipeContext({
  name: "Avatar",
  recipe: avatarRecipe,
});
// #endregion

type AvatarClassNames = VariantClassNames<AvatarRecipeSlot>;

type AvatarRootProps = AvatarPrimitiveRootProps &
  AvatarVariantProps &
  BaseAvatarRootProps;

export interface AvatarProps extends Omit<AvatarRootProps, "children"> {
  alt?: string;
  fallback?: JSX.Element;
  src?: string;
  classNames?: AvatarClassNames;
  fallbackProps?: Omit<AvatarFallbackProps, "children" | "class">;
  imageProps?: Omit<AvatarImageProps, "alt" | "class" | "src">;
}

const AvatarRoot: Component<AvatarRootProps> = withProvider(
  AvatarPrimitive.Root,
  { name: "Root", slot: "base" },
);

const AvatarImage: Component<AvatarImageProps> = withContext(
  AvatarPrimitive.Image,
  { name: "Image" },
);

const AvatarFallback: Component<AvatarFallbackProps> = withContext(
  AvatarPrimitive.Fallback,
  { name: "Fallback" },
);

export function Avatar(props: AvatarProps): JSX.Element {
  const [local, rest] = splitProps(props, [
    "shape",
    "size",
    "alt",
    "fallback",
    "fallbackProps",
    "imageProps",
    "src",
    "classNames",
  ]);

  return (
    <AvatarRoot {...rest} shape={local.shape} size={local.size}>
      <Show when={local.src}>
        <AvatarImage
          {...local.imageProps}
          alt={local.alt}
          class={local.classNames?.image}
          src={local.src}
        />
      </Show>
      <Show when={local.fallback !== undefined}>
        <AvatarFallback
          {...local.fallbackProps}
          class={local.classNames?.fallback}
        >
          {local.fallback}
        </AvatarFallback>
      </Show>
    </AvatarRoot>
  );
}

import { ark } from "@ark-ui/solid/factory";
import type { AvatarGroupProps as BaseAvatarGroupRootProps } from "@pisagor/props";
import { avatarGroupRecipe } from "@pisagor/recipes";
import type { Component, ComponentProps, JSX } from "solid-js";
import { For, Show, splitProps } from "solid-js";
import { createSlotRecipeContext } from "../../internal/create-slot-recipe-context";
import { Avatar } from "./avatar";

// #region Context
const { withContext, withProvider } = createSlotRecipeContext({
  name: "AvatarGroup",
  recipe: avatarGroupRecipe,
});
// #endregion

export interface AvatarGroupRootProps
  extends ComponentProps<typeof ark.div>,
    BaseAvatarGroupRootProps {}

export interface AvatarGroupProps
  extends Omit<AvatarGroupRootProps, "children"> {
  max?: number;
  users: Array<{ src?: string; fallback?: string; name?: string }>;
}

export type AvatarGroupCountProps = ComponentProps<typeof ark.div>;

export const AvatarGroupRoot: Component<AvatarGroupRootProps> = withProvider(
  ark.div,
  { name: "Root", slot: "base" },
);

export const AvatarGroupCount: Component<AvatarGroupCountProps> = withContext(
  ark.div,
  { name: "Count" },
);

export function AvatarGroupShorthand(props: AvatarGroupProps): JSX.Element {
  const [local, rest] = splitProps(props, ["max", "users"]);
  const visibleUsers = () =>
    local.max !== undefined ? local.users.slice(0, local.max) : local.users;
  const remainingCount = () =>
    local.max !== undefined && local.users.length > local.max
      ? local.users.length - local.max
      : 0;

  return (
    <AvatarGroupRoot {...rest}>
      <For each={visibleUsers()}>
        {(user) => (
          <Avatar
            alt={user.name ?? ""}
            fallback={user.fallback}
            src={user.src}
          />
        )}
      </For>
      <Show when={remainingCount() > 0}>
        <AvatarGroupCount>+{remainingCount()}</AvatarGroupCount>
      </Show>
    </AvatarGroupRoot>
  );
}

import {
  AvatarGroupCount,
  AvatarGroupRoot,
  AvatarGroupShorthand,
} from "./avatar-group";

export type {
  AvatarFallbackProps,
  AvatarImageProps,
} from "@ark-ui/solid/avatar";

export { Avatar, type AvatarProps } from "./avatar";
export type {
  AvatarGroupCountProps,
  AvatarGroupProps,
  AvatarGroupRootProps,
} from "./avatar-group";

export const AvatarGroup = Object.assign(AvatarGroupShorthand, {
  Count: AvatarGroupCount,
  Root: AvatarGroupRoot,
});

