function SelectionSummary<TData extends RowData>({
  onClear,
}: {
  onClear: () => void;
}) {
  const table = useDataGrid<TData>();
  const selected = table.getFilteredSelectedRowModel().rows.length;
  if (selected === 0) {
    return null;
  }
  return (
    <div class="flex items-center justify-between gap-3 pt-1">
      <p class="text-muted-foreground text-sm">{selected} selected</p>
      <Button onClick={onClear} size="sm" variant="ghost">
        Clear selection
      </Button>
    </div>
  );
}

function GlobalSelectionSummary<TData extends RowData>({
  onClear,
}: {
  onClear: () => void;
}) {
  return <SelectionSummary<TData> onClear={onClear} />;
}

export function GlobalSelection() {
  const [rowSelection, setRowSelection] = createSignal<RowSelectionState>({
    "2": true,
    "5": true,
