export function MultiGrouping() {
  const [grouping, setGrouping] = createSignal<GroupingState>([
    "department",
    "role",
  ]);
  const [expanded, setExpanded] = createSignal<ExpandedState>(true);

  const columns = createMemo<ColumnDef<User>[]>(() => [
    {
      accessorKey: "department",
      aggregationFn: "count",
      cell: ({ row }) => {
        if (row.getIsGrouped()) {
          return (
            <button
              class="inline-flex items-center gap-1.5 font-medium"
              onClick={row.getToggleExpandedHandler()}
              type="button"
            >
              {row.getIsExpanded() ? (
                <CaretDownIcon class="size-3.5" />
              ) : (
                <CaretRightIcon class="size-3.5" />
              )}
              {String(row.groupingValue)}
            </button>
          );
        }

        return row.original.department;
      },
      header: "Department",
    },
    {
      accessorKey: "role",
      aggregatedCell: ({ getValue }) => `${getValue()} users`,
      aggregationFn: "count",
      cell: ({ row }) =>
        row.getIsGrouped()
          ? `${row.groupingValue} (${row.subRows?.length ?? 0})`
          : row.original.role,
      header: "Role",
    },
    {
      accessorKey: "name",
      cell: ({ row }) => (row.getIsGrouped() ? null : row.original.name),
      header: "Name",
    },
    {
      accessorKey: "status",
      cell: ({ row }) =>
        row.getIsGrouped() ? null : (
          <Badge
            class="capitalize"
            variant={statusVariants[row.original.status]}
          >
            {row.original.status}
          </Badge>
        ),
      header: "Status",
    },
  ]);

  return (
    <DataGridShell>
      <DataGrid<User>
        columns={columns()}
        data={allUsers.slice(0, 30)}
        getRowId={(row: User) => row.id}
        onExpandedChange={setExpanded}
        onGroupingChange={setGrouping}
        state={{ expanded: expanded(), grouping: grouping() }}
      >
        <DataGrid.Toolbar>
          <p class="text-muted-foreground text-sm">
            Nested grouping by department, then role.
          </p>
        </DataGrid.Toolbar>
        <DataGridView colSpan={4} />
      </DataGrid>
    </DataGridShell>
  );
}

