  colSpan?: number;
  filterHead?: boolean;
}) {
  return (
    <Table>
      <Table.Header>
        <DataGrid.Header>
          <DataGrid.HeaderRow>
            <DataGrid.Head filter={filterHead} />
          </DataGrid.HeaderRow>
        </DataGrid.Header>
      </Table.Header>
      <Table.Body>
        <DataGrid.Body empty={<DataGrid.Empty colSpan={colSpan} />}>
          <DataGrid.Row>
            <DataGrid.Cell />
          </DataGrid.Row>
        </DataGrid.Body>
      </Table.Body>
    </Table>
  );
}

function useUserColumns(options?: {
  selectable?: boolean;
  sortable?: boolean;
}) {
  const { selectable = false, sortable = false } = options ?? {};

  return createMemo<ColumnDef<User>[]>(() => {
    type SortableHeaderColumn = {
      toggleSorting: (value: boolean) => void;
      getIsSorted: () => "asc" | "desc" | false;
    };

    const sortableHeader =
      (label: string) =>
      ({ column }: { column: SortableHeaderColumn }) => (
        <button
          class="inline-flex items-center gap-1.5 font-medium"
          onClick={() => column.toggleSorting(column.getIsSorted() === "asc")}
          type="button"
        >
          {label}
          <SortIndicator direction={column.getIsSorted()} />
        </button>
      );

    const columns: ColumnDef<User>[] = [];

    if (selectable) {
      columns.push({
        cell: ({ row }) => (
          <Checkbox
            aria-label={`Select ${row.original.name}`}
            checked={row.getIsSelected()}
            onCheckedChange={({ checked }) =>
              row.toggleSelected(checked === true)
            }
          />
        ),
        enableHiding: false,
        enableSorting: false,
        header: ({ table }) => (
          <Checkbox
            aria-label="Select all on page"
            checked={
              table.getIsAllPageRowsSelected()
                ? true
                : table.getIsSomePageRowsSelected()
                  ? "indeterminate"
                  : false
            }
            onCheckedChange={({ checked }) =>
              table.toggleAllPageRowsSelected(checked === true)
            }
          />
        ),
        id: "select",
        size: 40,
      });
    }

    columns.push(
      {
        accessorKey: "name",
        enableColumnFilter: true,
        enableGrouping: false,
        enableHiding: false,
        header: sortable ? sortableHeader("Name") : "Name",
      },
      {
        accessorKey: "email",
        enableColumnFilter: true,
        header: sortable ? sortableHeader("Email") : "Email",
      },
      {
        accessorKey: "role",
        enableColumnFilter: true,
        filterFn: "equals",
        header: sortable ? sortableHeader("Role") : "Role",
      },
      {
        accessorKey: "department",
        header: sortable ? sortableHeader("Department") : "Department",
      },
      {
        accessorKey: "status",
        cell: ({ row }) => (
          <Badge
            class="capitalize"
            variant={statusVariants[row.original.status]}
          >
            {row.original.status}
          </Badge>
        ),
        enableColumnFilter: true,
        filterFn: "equals",
        header: "Status",
      },
      {
        accessorKey: "joinedAt",
        cell: ({ row }) => formatDate(row.original.joinedAt),
        header: sortable ? sortableHeader("Joined") : "Joined",
        sortFn: "datetime",
      },
    );

    return columns;
  });
}

export function WithSortableData() {
  const [data, setData] = createSignal(allUsers.slice(0, 6));
  const itemIds = createMemo(() => data().map((user) => user.id));
  const columns = useUserColumns();

  return (
    <DataGridShell>
      <DataGrid<User>
        columns={columns()}
        data={data()}
        getRowId={(row) => row.id}
      >
        <DataGrid.Toolbar>
          <p class="text-muted-foreground text-sm">
            Compose Sortable outside the grid to reorder the shared{" "}
            <code class="text-xs">data</code> array; the table reflects the new
            order.
          </p>
        </DataGrid.Toolbar>
        <div class="flex flex-col gap-3">
          <Sortable
            items={itemIds()}
            onValueChange={(nextIds) => {
              setData((current) => {
                const byId = new Map(current.map((user) => [user.id, user]));

                return nextIds
                  .map((id) => byId.get(id))
                  .filter((user): user is User => user !== undefined);
              });
            }}
          >
            {data().map((user) => (
              <Sortable.Item value={user.id}>
                <Sortable.ItemContent>
                  <Sortable.Handle />
                  <div class="min-w-0 flex-1">
                    <p class="truncate font-medium text-sm">{user.name}</p>
                    <p class="truncate text-muted-foreground text-xs">
                      {user.email}
                    </p>
                  </div>
                  <Badge variant="secondary">{user.role}</Badge>
                </Sortable.ItemContent>
              </Sortable.Item>
            ))}
          </Sortable>
          <DataGridView colSpan={5} />
        </div>
      </DataGrid>
    </DataGridShell>
  );
}

