import {
  type FieldInputProps,
  FieldInput as InputPrimitive,
} from "@ark-ui/solid/field";
import type { InputProps as BaseInputProps } from "@pisagor/props";
import {
  type InputRecipeSlot,
  inputRecipe,
  inputRootRecipe,
} from "@pisagor/recipes";
import { cn } from "@pisagor/utils";
import type { JSX } from "solid-js";
import { Show, splitProps } from "solid-js";
import { useClearableInput } from "../../hooks";
import type { VariantClassNames } from "../../internal/types";
import { callEventHandler } from "../../utils";
import { InputGroupRoot } from "../input-group/input-group-core";
import { useFormControlSurface } from "../surface/use-form-control-surface";
import { InputClearAddon } from "./input-clear-button";

type FormControlVariant = "primary" | "secondary";
type InputClassNames = VariantClassNames<InputRecipeSlot>;
export interface InputProps
  extends Omit<FieldInputProps, "size">,
    BaseInputProps {
  /** Initial value when uncontrolled. Solid has no native defaultValue on inputs. */
  defaultValue?: string | number | readonly string[];
  clearable?: boolean;
  onValueChange?: (value: string) => void;
  rootRecipe?: typeof inputRootRecipe;
  classNames?: InputClassNames;
}

export function Input(props: InputProps): JSX.Element {
  const [local, rest] = splitProps(props, [
    "size",
    "variant",
    "clearable",
    "defaultValue",
    "disabled",
    "readOnly",
    "type",
    "value",
    "ref",
    "onChange",
    "onValueChange",
    "recipe",
    "rootRecipe",
    "class",
    "classNames",
  ]);

  const surfaceVariant = useFormControlSurface();
  const size = () => local.size ?? "md";
  const type = () => local.type ?? "text";
  const variant = () => local.variant ?? ("primary" as FormControlVariant);
  const clearable = () => local.clearable ?? false;
  const skipClearable = () =>
    !clearable() || type() === "file" || type() === "password";

  const { canClear, handleChange, handleClear, mergedRef } =
    useClearableInput<HTMLInputElement>({
      get clearable() {
        return clearable() && type() !== "file" && type() !== "password";
      },
      get defaultValue() {
        return local.defaultValue;
      },
      get disabled() {
        return local.disabled;
      },
      get onChange() {
        return (
          event: Event & {
            currentTarget: HTMLInputElement;
            target: HTMLInputElement;
          },
        ) => {
          callEventHandler(local.onChange, event);
        };
      },
      get onValueChange() {
        return local.onValueChange;
      },
      get readOnly() {
        return local.readOnly;
      },
      get ref() {
        return typeof local.ref === "function" ? local.ref : undefined;
      },
      get type() {
        return type();
      },
      get value() {
        return local.value;
      },
    });

  const shellArgs = () => ({
    surfaceVariant,
    variant: variant(),
  });
  const slots = () => (local.recipe ?? inputRecipe)();
  const rootRecipeFn = () => local.rootRecipe ?? inputRootRecipe;

  const applyDefaultValueRef = (el: HTMLInputElement) => {
    if (
      local.value === undefined &&
      local.defaultValue !== undefined &&
      el.value === ""
    ) {
      el.value = String(local.defaultValue);
    }
    if (typeof local.ref === "function") {
      local.ref(el);
    }
  };

  return (
    <Show
      fallback={
        <InputPrimitive
          {...rest}
          class={rootRecipeFn()({
            class: local.class,
            size: size(),
            ...shellArgs(),
          })}
          data-size={size()}
          data-variant={variant()}
          disabled={local.disabled}
          onChange={
            local.onChange || local.onValueChange
              ? (event) => {
                  callEventHandler(local.onChange, event);
                  local.onValueChange?.(event.currentTarget.value);
                }
              : undefined
          }
          readOnly={local.readOnly}
          ref={applyDefaultValueRef}
          type={type()}
          value={local.value}
        />
      }
      when={!skipClearable()}
    >
      <InputGroupRoot size={size()} variant={local.variant}>
        <InputPrimitive
          {...rest}
          class={slots().clearableRoot({
            class: cn(local.class, local.classNames?.clearableRoot),
          })}
          data-size={size()}
          disabled={local.disabled}
          onChange={handleChange}
          readOnly={local.readOnly}
          ref={mergedRef}
          type={type()}
          value={local.value}
        />
        <Show when={canClear()}>
          <InputClearAddon onClear={handleClear} />
        </Show>
      </InputGroupRoot>
    </Show>
  );
}

import type { JSX } from "solid-js";
import { splitProps } from "solid-js";
import {
  InputGroupAddon,
  InputGroupButton,
  type InputGroupButtonProps,
} from "../input-group/input-group-core";

interface InputClearButtonProps extends InputGroupButtonProps {
  onClear: () => void;
}

function XIcon() {
  return (
    <svg
      aria-hidden="true"
      fill="none"
      height="1em"
      viewBox="0 0 256 256"
      width="1em"
    >
      <path
        d="M205.66,194.34a8,8,0,0,1-11.32,11.32L128,139.31,61.66,205.66a8,8,0,0,1-11.32-11.32L116.69,128,50.34,61.66A8,8,0,0,1,61.66,50.34L128,116.69l66.34-66.35a8,8,0,0,1,11.32,11.32L139.31,128Z"
        fill="currentColor"
      />
    </svg>
  );
}

export function InputClearButton(props: InputClearButtonProps): JSX.Element {
  const [local, rest] = splitProps(props, ["onClear"]);

  return (
    <InputGroupButton
      {...rest}
      aria-label="Clear"
      data-part="clear-button"
      data-scope="input"
      onClick={local.onClear}
      size="icon-xs"
      type="button"
      variant="ghost"
    >
      <XIcon />
    </InputGroupButton>
  );
}

export function InputClearAddon(props: InputClearButtonProps): JSX.Element {
  const [local, rest] = splitProps(props, ["onClear"]);

  return (
    <InputGroupAddon align="inline-end">
      <InputClearButton {...rest} onClear={local.onClear} />
    </InputGroupAddon>
  );
}

import { Input as InputRoot } from "./input";
import { InputClearAddon, InputClearButton } from "./input-clear-button";

export type { InputProps } from "./input";

export const Input = Object.assign(InputRoot, {
  ClearAddon: InputClearAddon,
  ClearButton: InputClearButton,
});

