import { ark } from "@ark-ui/solid/factory";
import type { ItemProps as BaseItemProps } from "@pisagor/props";
import { type ItemVariantProps, itemRecipe } from "@pisagor/recipes";
import type { Component, ComponentProps, JSX } from "solid-js";
import { createMemo, splitProps } from "solid-js";
import { createSlotRecipeContext } from "../../internal/create-slot-recipe-context";
import { useItemGroup } from "./item-group.context";

// #region Context
const {
  Context: ItemStylesContext,
  useStyles: useItem,
  withContext,
} = createSlotRecipeContext({ name: "Item", recipe: itemRecipe });
// #endregion

export interface ItemProps
  extends ComponentProps<typeof ark.div>,
    BaseItemProps {}

export type ItemMediaProps = ComponentProps<typeof ark.div> & ItemVariantProps;
export type ItemHeaderProps = ComponentProps<typeof ark.div>;
export type ItemContentProps = ComponentProps<typeof ark.div>;
export type ItemTitleProps = ComponentProps<typeof ark.div>;
export type ItemDescriptionProps = ComponentProps<typeof ark.p>;
export type ItemActionsProps = ComponentProps<typeof ark.div>;
export type ItemFooterProps = ComponentProps<typeof ark.div>;

/** Inherits `variant` from the nearest ItemGroup when not set. */
export function ItemRoot(props: ItemProps): JSX.Element {
  const [local, rest] = splitProps(props, ["variant", "recipe", "class"]);
  const group = useItemGroup();
  const variant = () => local.variant ?? group?.variant ?? "default";
  const resolved = () => ({
    ...itemRecipe.defaultVariants,
    ...local.recipe?.defaultVariants,
    variant: variant(),
  });
  const slots = createMemo(() => (local.recipe ?? itemRecipe)(resolved()));

  return (
    <ItemStylesContext
      value={{
        get slots() {
          return slots();
        },
        get variants() {
          return resolved();
        },
      }}
    >
      <ark.div
        {...rest}
        class={slots().base({ class: local.class })}
        data-part="root"
        data-scope="item"
        data-variant={variant()}
      />
    </ItemStylesContext>
  );
}

export function ItemMedia(props: ItemMediaProps): JSX.Element {
  const [local, rest] = splitProps(props, ["variant", "children", "class"]);
  const styles = useItem();
  const variant = () => local.variant ?? "default";

  return (
    <ark.div
      {...rest}
      class={styles.slots.media({ class: local.class, variant: variant() })}
      data-part="media"
      data-scope="item"
      data-variant={variant()}
    >
      {local.children}
    </ark.div>
  );
}

export const ItemContent: Component<ItemContentProps> = withContext(ark.div, {
  name: "Content",
});

export const ItemTitle: Component<ItemTitleProps> = withContext(ark.div, {
  name: "Title",
});

export const ItemDescription: Component<ItemDescriptionProps> = withContext(
  ark.p,
  { name: "Description" },
);

export const ItemActions: Component<ItemActionsProps> = withContext(ark.div, {
  name: "Actions",
});

export const ItemHeader: Component<ItemHeaderProps> = withContext(ark.div, {
  name: "Header",
});

export const ItemFooter: Component<ItemFooterProps> = withContext(ark.div, {
  name: "Footer",
});

import type { ItemVariantProps } from "@pisagor/recipes";
import { createContext } from "../../utils";

export type ItemGroupContextValue = ItemVariantProps;

export const { ItemGroupContext, useItemGroup } = createContext(
  "ItemGroup",
)<ItemGroupContextValue>({ strict: false });

import { ark } from "@ark-ui/solid/factory";
import type {
  ItemProps as BaseItemGroupProps,
  ItemProps as BaseItemSeparatorProps,
} from "@pisagor/props";
import { itemRecipe } from "@pisagor/recipes";
import type { ComponentProps, JSX } from "solid-js";
import { splitProps } from "solid-js";
import { Separator, type SeparatorProps } from "../separator";
import { ItemGroupContext } from "./item-group.context";

export interface ItemGroupProps
  extends ComponentProps<typeof ark.div>,
    BaseItemGroupProps {}

export interface ItemSeparatorProps
  extends Omit<SeparatorProps, "recipe">,
    BaseItemSeparatorProps {}

export function ItemGroup(props: ItemGroupProps): JSX.Element {
  const [local, rest] = splitProps(props, [
    "variant",
    "children",
    "recipe",
    "class",
  ]);
  const variant = () => local.variant ?? "default";
  const slots = () => (local.recipe ?? itemRecipe)();

  return (
    <ItemGroupContext value={{ variant: variant() }}>
      <ark.div
        {...rest}
        class={slots().group({ class: local.class })}
        data-part="group"
        data-scope="item"
        data-variant={variant()}
        role="list"
      >
        {local.children}
      </ark.div>
    </ItemGroupContext>
  );
}

export function ItemSeparator(props: ItemSeparatorProps): JSX.Element {
  const [local, rest] = splitProps(props, ["recipe", "class"]);
  const slots = () => (local.recipe ?? itemRecipe)();

  return (
    <Separator
      {...rest}
      class={slots().separator({ class: local.class })}
      data-part="separator"
      data-scope="item"
      orientation="horizontal"
    />
  );
}

import {
  ItemActions,
  ItemContent,
  ItemDescription,
  ItemFooter,
  ItemHeader,
  ItemMedia,
  ItemRoot,
  ItemTitle,
} from "./item";
import { ItemGroup, ItemSeparator } from "./item-group";

export type {
  ItemActionsProps,
  ItemContentProps,
  ItemDescriptionProps,
  ItemFooterProps,
  ItemHeaderProps,
  ItemMediaProps,
  ItemProps,
  ItemTitleProps,
} from "./item";
export type { ItemGroupProps, ItemSeparatorProps } from "./item-group";

export const Item = Object.assign(ItemRoot, {
  Actions: ItemActions,
  Content: ItemContent,
  Description: ItemDescription,
  Footer: ItemFooter,
  Group: ItemGroup,
  Header: ItemHeader,
  Media: ItemMedia,
  Separator: ItemSeparator,
  Title: ItemTitle,
});

