export function Anchor() {
  return (
    <div>
      <Popover>
        <div class="flex items-center gap-2">
          <Popover.Trigger
            asChild={(props) => (
              <Button {...props()} variant="outline">
                Open
              </Button>
            )}
          />
          <Popover.Anchor
