export function QrCodeFrame(props: QrCodeFrameProps): JSX.Element {
  const [local, rest] = splitProps(props, ["class"]);
  const styles = useQrCode();
  return (
    <QrCodePrimitive.Frame
      {...rest}
      class={styles.slots.frame({ class: local.class })}
