import { ark } from "@ark-ui/solid/factory";
import type { SeparatorProps as BaseSeparatorProps } from "@pisagor/props";
import { separatorRecipe } from "@pisagor/recipes";
import type { ComponentProps, JSX } from "solid-js";
import { splitProps } from "solid-js";

export interface SeparatorProps
  extends ComponentProps<typeof ark.div>,
    BaseSeparatorProps {
  orientation?: "horizontal" | "vertical";
}

export function Separator(props: SeparatorProps): JSX.Element {
  const [local, rest] = splitProps(props, ["class", "recipe", "orientation"]);
  const recipeFn = () => local.recipe ?? separatorRecipe;

  return (
    <ark.div
      {...rest}
      aria-orientation={local.orientation ?? "horizontal"}
      class={recipeFn()({ class: local.class })}
      data-orientation={local.orientation ?? "horizontal"}
      data-part="root"
      data-scope="separator"
      role="separator"
    />
  );
}

import type {
  DialogCloseTriggerProps,
  DialogContentProps,
  DialogPositionerProps,
  DialogTriggerProps,
} from "@ark-ui/solid/dialog";
import { Dialog as DialogPrimitive } from "@ark-ui/solid/dialog";
import type { SheetProps as BaseSheetProps } from "@pisagor/props";
import { type SheetVariantProps, sheetRecipe } from "@pisagor/recipes";
import type { JSX } from "solid-js";
import { createMemo, Show, splitProps } from "solid-js";
import { Portal } from "solid-js/web";
import { createSlotRecipeContext } from "../internal/create-slot-recipe-context";
import { XIcon } from "../internal/icons";
import { Button } from "./button";
import type {
  DialogBackdropProps,
  DialogBodyProps,
  DialogDescriptionProps,
  DialogFooterProps,
  DialogHeaderProps,
  DialogRootProps,
  DialogTitleProps,
} from "./dialog";
import { Dialog } from "./dialog";

// #region Context
const { Context: SheetStylesContext, useStyles: useSheet } =
  createSlotRecipeContext({ name: "Sheet", recipe: sheetRecipe });
// #endregion

export type SheetPositionerProps = DialogPositionerProps & SheetVariantProps;

export interface SheetContentProps
  extends DialogContentProps,
    SheetVariantProps {
  showCloseButton?: boolean;
}

export interface SheetProps
  extends Omit<DialogRootProps, "recipe">,
    BaseSheetProps {}

export type SheetTriggerProps = DialogTriggerProps;
export type SheetCloseTriggerProps = DialogCloseTriggerProps;

export function SheetRoot(props: SheetProps): JSX.Element {
  const [local, rest] = splitProps(props, ["recipe"]);
  const slots = createMemo(() => (local.recipe ?? sheetRecipe)());

  return (
    <SheetStylesContext
      value={{
        get slots() {
          return slots();
        },
        variants: {},
      }}
    >
      <Dialog.Root {...rest} />
    </SheetStylesContext>
  );
}

export function SheetTrigger(props: SheetTriggerProps): JSX.Element {
  return <DialogPrimitive.Trigger {...props} />;
}

export function SheetBackdrop(props: DialogBackdropProps): JSX.Element {
  return <Dialog.Backdrop {...props} />;
}

export function SheetPositioner(props: SheetPositionerProps): JSX.Element {
  const [local, rest] = splitProps(props, ["placement", "variant", "class"]);
  const styles = useSheet();

  return (
    <DialogPrimitive.Positioner
      {...rest}
      class={styles.slots.positioner({
        class: local.class,
        placement: local.placement,
        variant: local.variant,
      })}
    />
  );
}

export function SheetContent(props: SheetContentProps): JSX.Element {
  const [local, rest] = splitProps(props, [
    "placement",
    "variant",
    "showCloseButton",
    "children",
    "class",
  ]);
  const styles = useSheet();
  const placement = () => local.placement ?? "right";
  const variant = () => local.variant ?? "default";
  const showCloseButton = () => local.showCloseButton ?? true;

  return (
    <Portal>
      <SheetBackdrop />
      <SheetPositioner placement={placement()} variant={variant()}>
        <DialogPrimitive.Content
          {...rest}
          class={styles.slots.content({
            class: local.class,
            placement: placement(),
            variant: variant(),
          })}
        >
          {local.children}
          <Show when={showCloseButton()}>
            <SheetCloseTrigger
              asChild={(triggerProps) => (
                <Button
                  {...triggerProps({ class: styles.slots.inline() })}
                  aria-label="Close"
                  size="icon-sm"
                  variant="ghost"
                >
                  <XIcon />
                </Button>
              )}
            />
          </Show>
        </DialogPrimitive.Content>
      </SheetPositioner>
    </Portal>
  );
}

export function SheetHeader(props: DialogHeaderProps): JSX.Element {
  return <Dialog.Header {...props} data-part="header" data-scope="sheet" />;
}

export function SheetTitle(props: DialogTitleProps): JSX.Element {
  return <Dialog.Title {...props} />;
}

export function SheetDescription(props: DialogDescriptionProps): JSX.Element {
  return <Dialog.Description {...props} />;
}

export function SheetBody(props: DialogBodyProps): JSX.Element {
  const [local, rest] = splitProps(props, ["class"]);
  const styles = useSheet();

  return (
    <Dialog.Body
      {...rest}
      class={styles.slots.body({ class: local.class })}
      data-part="body"
      data-scope="sheet"
    />
  );
}

export function SheetCloseTrigger(props: SheetCloseTriggerProps): JSX.Element {
  return <DialogPrimitive.CloseTrigger {...props} />;
}

export function SheetFooter(props: DialogFooterProps): JSX.Element {
  const [local, rest] = splitProps(props, ["class"]);
  const styles = useSheet();

  return (
    <Dialog.Footer
      {...rest}
      class={styles.slots.footer({ class: local.class })}
      data-part="footer"
      data-scope="sheet"
    />
  );
}

export const Sheet = Object.assign(SheetRoot, {
  Backdrop: SheetBackdrop,
  Body: SheetBody,
  CloseTrigger: SheetCloseTrigger,
  Content: SheetContent,
  Description: SheetDescription,
  Footer: SheetFooter,
  Header: SheetHeader,
  Positioner: SheetPositioner,
  Title: SheetTitle,
  Trigger: SheetTrigger,
});

import { ark } from "@ark-ui/solid/factory";
import type { SidebarProps as BaseSidebarProps } from "@pisagor/props";
import {
  type ButtonVariantProps,
  buttonRecipe,
  type SidebarRecipe,
  sidebarRecipe,
} from "@pisagor/recipes";
import { cn } from "@pisagor/utils";
import type { Accessor, ComponentProps, JSX } from "solid-js";
import {
  createEffect,
  createMemo,
  createSignal,
  onCleanup,
  Show,
  splitProps,
} from "solid-js";
import { useIsMobile } from "../hooks";
import { createSlotRecipeContext } from "../internal/create-slot-recipe-context";
import { SidebarSimpleIcon } from "../internal/icons";
import { createContext } from "../utils";
import { Button, type ButtonProps } from "./button";
import { Input, type InputProps } from "./input";
import { ScrollArea } from "./scroll-area";
import { Separator, type SeparatorProps } from "./separator";
import { Sheet, type SheetProps } from "./sheet";
import { Skeleton } from "./skeleton";
import { Tooltip, type TooltipProps } from "./tooltip";

// #region Context
const { Context: SidebarStylesContext, useStyles: useSidebarStyles } =
  createSlotRecipeContext({ name: "Sidebar", recipe: sidebarRecipe });

/** Open/collapse state shared by sidebar parts (not styles). */
interface SidebarState {
  readonly isMobile: Accessor<boolean>;
  readonly open: Accessor<boolean>;
  readonly openMobile: Accessor<boolean>;
  readonly setOpen: (open: boolean) => void;
  readonly setOpenMobile: (open: boolean) => void;
  readonly state: Accessor<"expanded" | "collapsed">;
  readonly toggleSidebar: () => void;
}

const { SidebarStateContext, useSidebarState } =
  createContext("SidebarState")<SidebarState>();

export interface SidebarContextProps extends SidebarState {
  /** Slot class recipes from `sidebarRecipe`. */
  readonly slots: SidebarRecipe;
}

/** Returns the nearest sidebar styles + state (`slots` stays reactive). */
export function useSidebar(): SidebarContextProps {
  const styles = useSidebarStyles();
  const state = useSidebarState();
  return {
    ...state,
    get slots() {
      return styles.slots;
    },
  };
}

// #endregion

export interface SidebarProviderProps
  extends ComponentProps<"div">,
    Pick<BaseSidebarProps, "recipe"> {
  defaultOpen?: boolean;
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
}

export interface SidebarProps
  extends Omit<SheetProps, "class" | "children" | "variant" | "recipe"> {
  placement?: "left" | "right";
  variant?: "sidebar" | "floating" | "inset";
  collapsible?: "offcanvas" | "icon" | "none";
  class?: string;
  children?: JSX.Element;
}

export interface SidebarContentProps extends ComponentProps<"div"> {
  scrollFade?: boolean;
}

export interface SidebarMenuButtonProps extends ButtonProps {
  isActive?: boolean;
  tooltip?: string | Omit<TooltipProps, "children">;
}

export interface SidebarMenuActionProps
  extends ComponentProps<typeof ark.button> {
  showOnHover?: boolean;
  buttonRecipe?: typeof buttonRecipe;
}

export interface SidebarMenuSkeletonProps
  extends ComponentProps<typeof ark.div> {
  showIcon?: boolean;
}

export interface SidebarMenuSubButtonProps
  extends ComponentProps<typeof ark.a>,
    ButtonVariantProps {
  isActive?: boolean;
  buttonRecipe?: typeof buttonRecipe;
}

export type SidebarRailProps = ComponentProps<typeof ark.button>;
export type SidebarInsetProps = ComponentProps<typeof ark.main>;
export type SidebarHeaderProps = ComponentProps<typeof ark.div>;
export type SidebarFooterProps = ComponentProps<typeof ark.div>;
export type SidebarGroupProps = ComponentProps<typeof ark.div>;
export type SidebarGroupLabelProps = ComponentProps<typeof ark.div>;

export interface SidebarGroupActionProps
  extends ComponentProps<typeof ark.button> {
  buttonRecipe?: typeof buttonRecipe;
}

export type SidebarGroupContentProps = ComponentProps<typeof ark.div>;
export type SidebarMenuProps = ComponentProps<typeof ark.ul>;
export type SidebarMenuItemProps = ComponentProps<typeof ark.li>;
export type SidebarMenuBadgeProps = ComponentProps<typeof ark.div>;
export type SidebarMenuSubProps = ComponentProps<typeof ark.ul>;
export type SidebarMenuSubItemProps = ComponentProps<typeof ark.li>;

const SIDEBAR_STORAGE_KEY = "sidebar_state";
const SIDEBAR_WIDTH = "16rem";
const SIDEBAR_WIDTH_MOBILE = "18rem";
const SIDEBAR_WIDTH_ICON = "3rem";

export function SidebarProvider(props: SidebarProviderProps): JSX.Element {
  const [local, rest] = splitProps(props, [
    "defaultOpen",
    "open",
    "onOpenChange",
    "recipe",
    "class",
    "style",
    "children",
  ]);

  const isMobile = useIsMobile();
  const [openMobile, setOpenMobile] = createSignal(false);
  const [uncontrolledOpen, setUncontrolledOpen] = createSignal(
    local.defaultOpen ?? true,
  );

  const open = createMemo(() =>
    local.open !== undefined ? !!local.open : uncontrolledOpen(),
  );

  const setOpen = (value: boolean) => {
    if (local.open === undefined) {
      setUncontrolledOpen(value);
    }
    local.onOpenChange?.(value);
    if (typeof localStorage !== "undefined") {
      localStorage.setItem(SIDEBAR_STORAGE_KEY, String(value));
    }
  };

  const toggleSidebar = () => {
    if (isMobile()) {
      setOpenMobile((v) => !v);
    } else {
      setOpen(!open());
    }
  };

  createEffect(() => {
    const onKeyDown = (event: KeyboardEvent) => {
      if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === "b") {
        event.preventDefault();
        toggleSidebar();
      }
    };
    window.addEventListener("keydown", onKeyDown);
    onCleanup(() => window.removeEventListener("keydown", onKeyDown));
  });

  const state = createMemo<"expanded" | "collapsed">(() =>
    open() ? "expanded" : "collapsed",
  );
  const stateValue: SidebarState = {
    isMobile,
    open,
    openMobile,
    setOpen,
    setOpenMobile,
    state,
    toggleSidebar,
  };

  const style = () => {
    const base: Record<string, string> = {
      "--sidebar-width": SIDEBAR_WIDTH,
      "--sidebar-width-icon": SIDEBAR_WIDTH_ICON,
    };
    const s = local.style;
    if (s && typeof s === "object" && !Array.isArray(s)) {
      return { ...base, ...(s as Record<string, string>) };
    }
    return base;
  };

  const slots = createMemo(() => (local.recipe ?? sidebarRecipe)());

  return (
    <SidebarStylesContext
      value={{
        get slots() {
          return slots();
        },
        variants: {},
      }}
    >
      <SidebarStateContext value={stateValue}>
        <ark.div
          {...rest}
          class={slots().wrapper({ class: local.class })}
          data-part="wrapper"
          data-scope="sidebar"
          style={style()}
        >
          {local.children}
        </ark.div>
      </SidebarStateContext>
    </SidebarStylesContext>
  );
}

export function SidebarRoot(props: SidebarProps): JSX.Element {
  const [local, rest] = splitProps(props, [
    "collapsible",
    "placement",
    "variant",
    "class",
    "children",
  ]);
  const styles = useSidebarStyles();
  const { isMobile, openMobile, setOpenMobile, state } = useSidebarState();
  const collapsible = () => local.collapsible ?? "offcanvas";
  const placement = () => local.placement ?? "left";
  const variant = () => local.variant ?? "sidebar";
  const padded = () => variant() === "floating" || variant() === "inset";

  return (
    <Show
      fallback={
        <Show
          fallback={
            <ark.div
              {...rest}
              class={styles.slots.peer({ class: local.class })}
              data-collapsible={state() === "collapsed" ? collapsible() : ""}
              data-part="root"
              data-placement={placement()}
              data-scope="sidebar"
              data-state={state()}
              data-variant={variant()}
            >
              <ark.div
                class={styles.slots.gap({
                  padded: padded(),
                  placement: placement(),
                })}
                data-part="gap"
                data-scope="sidebar"
              />
              <ark.div
                class={styles.slots.container({
                  class: local.class,
                  padded: padded(),
                  placement: placement(),
                })}
                data-part="container"
                data-scope="sidebar"
              >
                <ark.div
                  class={styles.slots.inner()}
                  data-part="inner"
                  data-scope="sidebar"
                  data-sidebar="sidebar"
                >
                  {local.children}
                </ark.div>
              </ark.div>
            </ark.div>
          }
          when={isMobile()}
        >
          <Sheet
            onOpenChange={(details) => setOpenMobile(details.open)}
            open={openMobile()}
          >
            <Sheet.Content
              {...rest}
              class={styles.slots.mobile()}
              data-mobile="true"
              data-sidebar="sidebar"
              placement={placement() === "left" ? "left" : "right"}
              style={{ "--sidebar-width": SIDEBAR_WIDTH_MOBILE }}
            >
              <Sheet.Header class={styles.slots.mobileHeader()}>
                <Sheet.Title>Sidebar</Sheet.Title>
                <Sheet.Description>
                  Displays the mobile sidebar.
                </Sheet.Description>
              </Sheet.Header>
              <ark.div class={styles.slots.mobileBody()}>
                {local.children}
              </ark.div>
            </Sheet.Content>
          </Sheet>
        </Show>
      }
      when={collapsible() === "none"}
    >
      <ark.div
        {...rest}
        class={styles.slots.base({ class: local.class })}
        data-part="root"
        data-scope="sidebar"
      >
        {local.children}
      </ark.div>
    </Show>
  );
}

export function SidebarTrigger(props: ButtonProps): JSX.Element {
  const [local, rest] = splitProps(props, ["onClick", "class"]);
  const styles = useSidebarStyles();
  const { toggleSidebar } = useSidebarState();

  return (
    <Button
      {...rest}
      class={styles.slots.trigger({ class: local.class })}
      data-part="trigger"
      data-scope="sidebar"
      data-sidebar="trigger"
      onClick={(event) => {
        if (typeof local.onClick === "function") local.onClick(event);
        toggleSidebar();
      }}
      size="icon-md"
      variant="ghost"
    >
      <SidebarSimpleIcon class={styles.slots.triggerIcon()} />
      <ark.span class={styles.slots.triggerLabel()}>Toggle sidebar</ark.span>
    </Button>
  );
}

export function SidebarRail(props: SidebarRailProps): JSX.Element {
  const [local, rest] = splitProps(props, ["class"]);
  const styles = useSidebarStyles();
  const { toggleSidebar } = useSidebarState();

  return (
    <ark.button
      {...rest}
      aria-label="Toggle sidebar"
      class={styles.slots.rail({ class: local.class })}
      data-part="rail"
      data-scope="sidebar"
      data-sidebar="rail"
      onClick={toggleSidebar}
      tabIndex={-1}
      title="Toggle sidebar"
      type="button"
    />
  );
}

export function SidebarInset(props: SidebarInsetProps): JSX.Element {
  const [local, rest] = splitProps(props, ["class"]);
  const styles = useSidebarStyles();

  return (
    <ark.main
      {...rest}
      class={styles.slots.inset({ class: local.class })}
      data-part="inset"
      data-scope="sidebar"
    />
  );
}

export function SidebarInput(props: InputProps): JSX.Element {
  const [local, rest] = splitProps(props, ["class", "classNames"]);
  const styles = useSidebarStyles();
  return (
    <Input
      {...rest}
      class={styles.slots.input({ class: local.class })}
      classNames={local.classNames}
      data-sidebar="input"
    />
  );
}

export function SidebarHeader(props: SidebarHeaderProps): JSX.Element {
  const [local, rest] = splitProps(props, ["class"]);
  const styles = useSidebarStyles();

  return (
    <ark.div
      {...rest}
      class={styles.slots.header({ class: local.class })}
      data-part="header"
      data-scope="sidebar"
      data-sidebar="header"
    />
  );
}

export function SidebarFooter(props: SidebarFooterProps): JSX.Element {
  const [local, rest] = splitProps(props, ["class"]);
  const styles = useSidebarStyles();

  return (
    <ark.div
      {...rest}
      class={styles.slots.footer({ class: local.class })}
      data-part="footer"
      data-scope="sidebar"
      data-sidebar="footer"
    />
