}

export function SidebarSeparator(props: SeparatorProps): JSX.Element {
  const [local, rest] = splitProps(props, ["class"]);
  const styles = useSidebarStyles();

  return (
    <Separator
      {...rest}
      class={styles.slots.separator({ class: local.class })}
      data-part="separator"
      data-scope="sidebar"
      data-sidebar="separator"
    />
  );
}

export function SidebarContent(props: SidebarContentProps): JSX.Element {
  const [local, rest] = splitProps(props, ["scrollFade", "class"]);
  const styles = useSidebarStyles();
  return (
    <ScrollArea
      class={styles.slots.scrollArea()}
      scrollFade={local.scrollFade ?? false}
    >
      <ark.div
        {...rest}
        class={styles.slots.content({ class: local.class })}
        data-part="content"
        data-scope="sidebar"
        data-sidebar="content"
      />
    </ScrollArea>
  );
}

export function SidebarGroup(props: SidebarGroupProps): JSX.Element {
  const [local, rest] = splitProps(props, ["class"]);
  const styles = useSidebarStyles();

  return (
    <ark.div
      {...rest}
      class={styles.slots.group({ class: local.class })}
      data-part="group"
      data-scope="sidebar"
      data-sidebar="group"
    />
  );
}

export function SidebarGroupLabel(props: SidebarGroupLabelProps): JSX.Element {
  const [local, rest] = splitProps(props, ["class"]);
  const styles = useSidebarStyles();

  return (
    <ark.div
      {...rest}
      class={styles.slots.groupLabel({ class: local.class })}
      data-part="group-label"
      data-scope="sidebar"
      data-sidebar="group-label"
    />
  );
}

export function SidebarGroupAction(
  props: SidebarGroupActionProps,
): JSX.Element {
  const [local, rest] = splitProps(props, ["buttonRecipe", "class"]);
  const styles = useSidebarStyles();
  const recipe = () => local.buttonRecipe ?? buttonRecipe;

  return (
    <ark.button
      {...rest}
      class={cn(
        recipe()({
          clickEffect: false,
          size: "icon-xs",
          variant: "ghost",
        }).base(),
        styles.slots.groupAction(),
        local.class,
      )}
      data-part="group-action"
      data-scope="sidebar"
      data-sidebar="group-action"
      type="button"
    />
  );
}

export function SidebarGroupContent(
  props: SidebarGroupContentProps,
): JSX.Element {
  const [local, rest] = splitProps(props, ["class"]);
  const styles = useSidebarStyles();

  return (
    <ark.div
      {...rest}
      class={styles.slots.groupContent({ class: local.class })}
      data-part="group-content"
      data-scope="sidebar"
      data-sidebar="group-content"
    />
  );
}

export function SidebarMenu(props: SidebarMenuProps): JSX.Element {
  const [local, rest] = splitProps(props, ["class"]);
  const styles = useSidebarStyles();

  return (
    <ark.ul
      {...rest}
      class={styles.slots.menu({ class: local.class })}
      data-part="menu"
      data-scope="sidebar"
      data-sidebar="menu"
    />
  );
}

export function SidebarMenuItem(props: SidebarMenuItemProps): JSX.Element {
  const [local, rest] = splitProps(props, ["class"]);
  const styles = useSidebarStyles();

  return (
    <ark.li
      {...rest}
      class={styles.slots.menuItem({ class: local.class })}
      data-part="menu-item"
      data-scope="sidebar"
      data-sidebar="menu-item"
    />
  );
}

export function SidebarMenuButton(props: SidebarMenuButtonProps): JSX.Element {
  const [local, rest] = splitProps(props, [
    "size",
    "variant",
    "isActive",
    "tooltip",
    "class",
    "children",
  ]);
  const styles = useSidebarStyles();
  const { isMobile, state } = useSidebarState();
  const size = () => local.size ?? "md";
  const variant = () => local.variant ?? "ghost";

  const button = (
    <Button
      {...rest}
      class={styles.slots.menuButton({ class: local.class })}
      clickEffect={false}
      data-active={local.isActive ?? false}
      data-part="menu-button"
      data-scope="sidebar"
      data-sidebar="menu-button"
      data-size={size()}
      size={size()}
      variant={variant()}
    >
      {local.children}
    </Button>
  );

  return (
    <Show fallback={button} when={local.tooltip}>
      {(tip) => {
        const tooltipProps =
          typeof tip() === "string"
            ? ({ content: tip() as string } as Omit<TooltipProps, "children">)
            : (tip() as Omit<TooltipProps, "children">);
        return (
          <Tooltip
            {...tooltipProps}
            contentProps={{
              ...tooltipProps.contentProps,
              hidden: state() !== "collapsed" || isMobile(),
            }}
            positioning={{ placement: "right", ...tooltipProps.positioning }}
          >
            {button}
          </Tooltip>
        );
      }}
    </Show>
  );
}

export function SidebarMenuAction(props: SidebarMenuActionProps): JSX.Element {
  const [local, rest] = splitProps(props, [
    "showOnHover",
    "buttonRecipe",
    "class",
  ]);
  const styles = useSidebarStyles();
  const recipe = () => local.buttonRecipe ?? buttonRecipe;
  const showOnHover = () => local.showOnHover ?? false;

  return (
    <ark.button
      {...rest}
      class={cn(
        recipe()({
          clickEffect: false,
          size: "icon-xs",
          variant: "ghost",
        }).base(),
        styles.slots.menuAction(),
        !showOnHover() &&
          "group-focus-within/menu-item:opacity-100 group-hover/menu-item:opacity-100 data-[state=open]:opacity-100 peer-data-[active=true]/menu-button:text-accent-foreground md:opacity-0",
        local.class,
      )}
      data-part="menu-action"
      data-scope="sidebar"
      data-sidebar="menu-action"
      type="button"
    />
  );
}

export function SidebarMenuBadge(props: SidebarMenuBadgeProps): JSX.Element {
  const [local, rest] = splitProps(props, ["class"]);
  const styles = useSidebarStyles();

  return (
    <ark.div
      {...rest}
      class={styles.slots.menuBadge({ class: local.class })}
      data-part="menu-badge"
      data-scope="sidebar"
      data-sidebar="menu-badge"
    />
  );
}

export function SidebarMenuSkeleton(
  props: SidebarMenuSkeletonProps,
): JSX.Element {
  const [local, rest] = splitProps(props, ["showIcon", "class"]);
  const styles = useSidebarStyles();

  return (
    <ark.div
      {...rest}
      class={styles.slots.menuSkeleton({ class: local.class })}
      data-part="menu-skeleton"
      data-scope="sidebar"
      data-sidebar="menu-skeleton"
    >
      <Show when={local.showIcon}>
        <Skeleton
          class={styles.slots.menuSkeletonIcon()}
          data-sidebar="menu-skeleton-icon"
        />
      </Show>
      <Skeleton
        class={styles.slots.menuSkeletonText()}
        data-sidebar="menu-skeleton-text"
        style={{ "--skeleton-width": "70%" }}
      />
    </ark.div>
  );
}

export function SidebarMenuSub(props: SidebarMenuSubProps): JSX.Element {
  const [local, rest] = splitProps(props, ["class"]);
  const styles = useSidebarStyles();

  return (
    <ark.ul
      {...rest}
      class={styles.slots.menuSub({ class: local.class })}
      data-part="menu-sub"
      data-scope="sidebar"
      data-sidebar="menu-sub"
    />
  );
}

export function SidebarMenuSubItem(
  props: SidebarMenuSubItemProps,
): JSX.Element {
  const [local, rest] = splitProps(props, ["class"]);
  const styles = useSidebarStyles();

  return (
    <ark.li
      {...rest}
      class={styles.slots.menuSubItem({ class: local.class })}
      data-part="menu-sub-item"
      data-scope="sidebar"
      data-sidebar="menu-sub-item"
    />
  );
}

export function SidebarMenuSubButton(
  props: SidebarMenuSubButtonProps,
): JSX.Element {
  const [local, rest] = splitProps(props, [
    "size",
    "isActive",
    "buttonRecipe",
    "class",
  ]);
  const styles = useSidebarStyles();
  const size = () => local.size ?? "md";
  const recipe = () => local.buttonRecipe ?? buttonRecipe;

  return (
    <ark.a
      {...rest}
      class={cn(
        recipe()({ clickEffect: false, size: size(), variant: "ghost" }).base(),
        styles.slots.menuSubButton(),
        local.class,
      )}
      data-active={local.isActive ?? false}
      data-part="menu-sub-button"
      data-scope="sidebar"
      data-sidebar="menu-sub-button"
      data-size={size()}
    />
  );
}

export const Sidebar = Object.assign(SidebarRoot, {
  Content: SidebarContent,
  Footer: SidebarFooter,
  Group: SidebarGroup,
  GroupAction: SidebarGroupAction,
  GroupContent: SidebarGroupContent,
  GroupLabel: SidebarGroupLabel,
  Header: SidebarHeader,
  Input: SidebarInput,
  Inset: SidebarInset,
  Menu: SidebarMenu,
  MenuAction: SidebarMenuAction,
  MenuBadge: SidebarMenuBadge,
  MenuButton: SidebarMenuButton,
  MenuItem: SidebarMenuItem,
  MenuSkeleton: SidebarMenuSkeleton,
  MenuSub: SidebarMenuSub,
  MenuSubButton: SidebarMenuSubButton,
  MenuSubItem: SidebarMenuSubItem,
  Provider: SidebarProvider,
  Rail: SidebarRail,
  Separator: SidebarSeparator,
  Trigger: SidebarTrigger,
});

