import { SignaturePad } from "@pisagor/solid";
import { createSignal } from "solid-js";
export function Controlled() {
  const [paths, setPaths] = createSignal<string[]>([]);

  return (
    <SignaturePad
      onDraw={(details) => setPaths(details.paths)}
      onDrawEnd={(details) => setPaths(details.paths)}
      paths={paths()}
    />
  );
}

import { SignaturePad } from "@pisagor/solid";

export function Default() {
  return <SignaturePad />;
}

import { SignaturePad } from "@pisagor/solid";

export function Disabled() {
  return <SignaturePad disabled />;
}

import { Field, SignaturePad } from "@pisagor/solid";
import { createSignal } from "solid-js";
export function ImagePreview() {
  const [imageUrl, setImageUrl] = createSignal<string | null>(null);

  return (
    <Field class="flex flex-col gap-2">
      <SignaturePad
        onDrawEnd={(details) =>
          details.getDataUrl("image/png").then((url) => setImageUrl(url))
        }
      />
      <Field.Description>Image preview</Field.Description>
      <div class="relative h-40 w-full rounded-lg border bg-muted">
        {imageUrl() && (
          <img
            alt="Your signature as captured from the pad above"
            class="size-full dark:invert"
            src={imageUrl() ?? undefined}
            style={{
              height: "100%",
              inset: 0,
              "object-fit": "cover",
              position: "absolute",
              width: "100%",
            }}
          />
        )}
      </div>
    </Field>
  );
}

import { SignaturePad } from "@pisagor/solid";

export function Invalid() {
  return <SignaturePad invalid />;
}

