        <Swap
          off={<SunIcon />}
          on={<MoonIcon />}
          swap={fade()}
          variant="fade"
        />
      </Button>
      <Button
        aria-label="Toggle theme"
        onClick={() => setBlur(!blur)}
        size="icon-lg"
        variant="outline"
      >
        <Swap
          off={<SunIcon />}
          on={<MoonIcon />}
          swap={blur()}
          variant="blur"
        />
      </Button>
      <Button
        aria-label="Toggle theme"
        onClick={() => setFlip(!flip)}
        size="icon-lg"
        variant="outline"
      >
        <Swap
