          on={<MoonIcon />}
          swap={flip()}
          variant="flip"
        />
      </Button>
      <Button
        aria-label="Toggle theme"
        onClick={() => setRotate(!rotate)}
        size="icon-lg"
        variant="outline"
      >
        <Swap
