import type { TourStepType } from "@pisagor/solid";
import { Button, Tour } from "@pisagor/solid";
export function Async() {
  const steps: TourStepType[] = [
    {
      actions: [{ action: "next", label: "Next" }],
      description: "This tour demonstrates loading data before showing a step.",
      id: "intro",
      title: "Async data loading",
      type: "dialog",
    },
    {
      actions: [
        { action: "prev", label: "Back" },
        { action: "next", label: "Next" },
      ],
      description: "Fetching user data...",
      effect({ show, update }) {
        const timer = window.setTimeout(() => {
          update({
            description: "You have 12 projects and 48 team members.",
            title: "Welcome, Jane Doe",
          });
          show();
        }, 800);

        return () => window.clearTimeout(timer);
      },
      id: "user-info",
      target: () => document.querySelector<HTMLElement>("#user-card"),
      title: "Loading...",
      type: "tooltip",
    },
    {
      actions: [{ action: "dismiss", label: "Done" }],
      description:
        "The async step loaded data from the GitHub API before displaying.",
      id: "complete",
      title: "Tour complete",
      type: "dialog",
    },
  ];
  return (
    <div class="flex flex-col gap-2">
      <Tour steps={steps}>
        <Tour.Trigger
          asChild={(props) => (
            <Button {...props()} variant="outline">
              Start tour
            </Button>
          )}
        />
        <div
          class="flex items-center justify-center rounded-lg border border-border bg-muted px-8 py-4 font-medium text-sm"
          id="user-card"
        >
          User profile card
        </div>
        <Tour.Content>
          <Tour.Header>
            <Tour.ProgressText />
            <Tour.Title />
            <Tour.Description />
          </Tour.Header>
          <Tour.Actions />
        </Tour.Content>
      </Tour>
    </div>
  );
}

import type { TourStepType } from "@pisagor/solid";
import { Button, Tour } from "@pisagor/solid";
export function CustomSpacing() {
  const steps: TourStepType[] = [
    {
      actions: [{ action: "next" as const, label: "Next" }],
      description:
        "`Tour.Content` uses `[--space:--spacing(2)]` here for tighter padding than the default.",
      id: "step-1",
      title: "Custom spacing",
      type: "dialog",
    },
    {
      actions: [{ action: "dismiss" as const, label: "Done" }],
      description:
        "You can pair `[--space]` with responsive variants, for example `md:[--space:--spacing(6)]`.",
      id: "step-2",
      title: "Breakpoint utilities",
      type: "dialog",
    },
  ];
  return (
    <Tour steps={steps}>
      <Tour.Trigger
        asChild={(props) => (
          <Button {...props()} variant="outline">
            Open
          </Button>
        )}
      />
      <Tour.Content class="[--space:--spacing(2)]">
        <Tour.Header>
          <Tour.ProgressText />
          <Tour.Title />
          <Tour.Description />
        </Tour.Header>
        <Tour.Footer>
          <Tour.PreviousStep />
          <Tour.NextStep />
        </Tour.Footer>
      </Tour.Content>
    </Tour>
  );
}

import { Button, Tour } from "@pisagor/solid";

export function Default() {
  return (
    <Tour
      steps={[
        {
          actions: [{ action: "next", label: "Next" }],
          description: "This is the first step.",
          id: "step-1",
          title: "Welcome",
        },
        {
          actions: [{ action: "dismiss", label: "Close" }],
          description: "Tour complete.",
          id: "step-2",
          title: "Done",
        },
      ]}
    >
      <Tour.Trigger
        asChild={(props) => <Button {...props()}>Start tour</Button>}
      />
      <Tour.Content />
    </Tour>
  );
}

import type { TourStepType } from "@pisagor/solid";
import { Button, Tour } from "@pisagor/solid";
import { createSignal, For } from "solid-js";

export function Events() {
  const steps: TourStepType[] = [
    {
      actions: [{ action: "next", label: "Next" }],
      description: "Watch the event log below as you navigate.",
      id: "step-1",
      target: () => document.querySelector<HTMLElement>("#event-1"),
      title: "First step",
      type: "tooltip",
    },
    {
      actions: [
        { action: "prev", label: "Back" },
        { action: "next", label: "Next" },
      ],
      description: "Each step change triggers an event.",
      id: "step-2",
      target: () => document.querySelector<HTMLElement>("#event-2"),
      title: "Second step",
      type: "tooltip",
    },
    {
      actions: [
        { action: "prev", label: "Back" },
        { action: "dismiss", label: "Finish" },
      ],
      description: "Complete the tour to see the status change.",
      id: "step-3",
      target: () => document.querySelector<HTMLElement>("#event-3"),
      title: "Final step",
      type: "tooltip",
    },
  ];
  const [logs, setLogs] = createSignal<{ id: number; message: string }[]>([]);
  let nextLogId = 0;

  const addLog = (message: string) => {
    nextLogId += 1;
    setLogs((prev) => [...prev, { id: nextLogId, message }]);
  };

  return (
    <div class="flex flex-col gap-2">
      <Tour
        onStatusChange={(details) => addLog(`Status: ${details.status}`)}
        onStepChange={(details) =>
          addLog(`Step changed: ${details.stepId ?? "unknown"}`)
        }
        steps={steps}
      >
        <Tour.Trigger
          asChild={(props) => (
            <Button {...props()} variant="outline">
              Start tour
            </Button>
          )}
        />
        <div class="flex flex-wrap gap-2">
          <div
            class="flex items-center justify-center rounded-md border bg-popover px-6 py-4 font-medium"
            id="event-1"
          >
            Step 1
          </div>
          <div
            class="flex items-center justify-center rounded-md border bg-popover px-6 py-4 font-medium"
            id="event-2"
          >
            Step 2
          </div>
          <div
            class="flex items-center justify-center rounded-md border bg-popover px-6 py-4 font-medium"
            id="event-3"
          >
            Step 3
          </div>
        </div>
        <div class="flex h-32 flex-col gap-1 overflow-y-auto rounded-md border bg-muted p-3 font-mono text-muted-foreground text-xs">
          <strong>Event Log:</strong>
          {logs().length === 0 ? (
            <span>Start the tour to see events</span>
          ) : (
            <For each={logs()}>{(log) => <span>{log.message}</span>}</For>
          )}
        </div>
        <Tour.Content>
          <Tour.Header>
            <Tour.ProgressText />
            <Tour.Title />
            <Tour.Description />
          </Tour.Header>
          <Tour.Footer>
            <Tour.Actions />
          </Tour.Footer>
        </Tour.Content>
      </Tour>
    </div>
  );
}

